{
  "findings": [
    {
      "check_id": "CKV_AWS_53",
      "title": "Ensure S3 bucket has block public ACLS enabled",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "CRITICAL",
      "explanation": "The S3 bucket is not configured to block public ACLs, potentially allowing unauthorized access."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket lacks a Public Access block, which could lead to unintended public exposure."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have access logging enabled, making it difficult to track and monitor access."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"admin_dashboard\" {\n  bucket = \"smart-city-parking-management-system-s3-admin-dashboard-${random_string.bucket_suffix.result}\"\n}\n\nresource \"aws_s3_bucket_public_access_block\" \"admin_dashboard\" {\n  bucket = aws_s3_bucket.admin_dashboard.id\n\n  block_public_acls   = true\n  block_public_policy = true\n  ignore_public_acls  = true\n  restrict_public_buckets = true\n}\n\nresource \"aws_s3_bucket_logging\" \"admin_dashboard\" {\n  bucket = aws_s3_bucket.admin_dashboard.id\n\n  target_bucket = \"${aws_s3_bucket.admin_dashboard.id}-logs\"\n  target_prefix = \"/logs/\"\n}",
  "fix_summary": "Added aws_s3_bucket_public_access_block to block public access and aws_s3_bucket_logging to enable access logging for the S3 bucket."
}
